// === HIER PFLEGEN ===
const CONFIG = {
  // Live: https://api-m.paypal.com · Sandbox: https://api-m.sandbox.paypal.com
  paypalBaseUrl: 'https://api-m.paypal.com',
  // Das Buch: Artikelnummer, und für Positionen ohne Artikelnummer die Bezeichnung
  sku: 'EX-2026-02-03',
  bezeichnung: 'Honesty 3 EXKLUSIVAUSGABE',
  // Nicht gesucht: Shopify-Bestellungen (eigener Flow) und A-Aufträge (werden nicht bearbeitet) – regulärer Ausdruck auf die Bestellnummer
  ausschliessen: '^(BB|A)-',
  // Gesucht wird je Bestellung vom Vortag bis so viele Tage nach dem Bestelldatum
  suchPufferTage: 14,
  // PayPal liefert je Suche höchstens 10.000 Transaktionen und kennt keinen Filter nach Rechnungsnummer.
  // Darum eine Suche je Bestellung, eingegrenzt auf den Bestellbetrag ± diese Toleranz in Euro
  betragToleranz: 1,
  // Das Präfix ist für alle Bestellungen gleich: nur so viele Bestellungen suchen, gleichmäßig über den Zeitraum verteilt. 0 = alle
  stichprobe: 50,
  spalten: {
    bestellnummer: 'Auftragsnummer',
    datum: 'Auftragsdatum',
    betrag: 'Betrag',
    artikelnummer: 'Artikelnummer',
    bezeichnung: 'Bezeichnung (Position)'
  }
};

// Bereinigen wie im Haupt-Flow: BOM vor dem ersten Spaltennamen, Apostrophe um Werte, NULL = leer
const sauber = v => {
  const s = String(v ?? '').trim().replace(/^'(.*)'$/s, '$1');
  return s === 'NULL' ? '' : s;
};
const rows = $input.all().map(i => Object.fromEntries(
  Object.entries(i.json).map(([k, v]) => [k.replace(/^﻿/, '').trim(), sauber(v)])
));
const S = CONFIG.spalten;
// Fehlende Spalte in der ersten Zeile = Spalte fehlt im Export (n8n lässt nur leere Werte weg, nicht die Bestellnummer)
const fehlend = [S.bestellnummer, S.datum, S.betrag, S.bezeichnung].filter(s => !rows.length || !(s in rows[0]));
if (fehlend.length) {
  throw new Error(`Spalte(n) fehlen: ${fehlend.join(', ')} – vorhanden: ${Object.keys(rows[0] || {}).join(', ')}`);
}

const norm = s => String(s || '').trim().toLowerCase();
const zahl = v => {
  const s = String(v ?? '').trim().replace(/[\s€]/g, '');
  return Number(s.includes(',') ? s.replace(/\./g, '').replace(',', '.') : s);
};
const datum = v => {
  const m = String(v ?? '').trim().match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})/);
  const d = m ? new Date(Date.UTC(Number(m[3]), Number(m[2]) - 1, Number(m[1]))) : new Date(v);
  return isNaN(d) ? null : d.toISOString().slice(0, 10);
};
const ausschluss = new RegExp(CONFIG.ausschliessen);

// Bestellungen mit dem Buch: Artikelnummer, oder ohne Artikelnummer über die Bezeichnung
const bestellungen = new Map();
for (const r of rows) {
  const nr = r[S.bestellnummer];
  if (!nr || ausschluss.test(nr)) continue;
  if (!bestellungen.has(nr)) bestellungen.set(nr, { bestellnummer: nr, bestelldatum: null, betragExport: null, honesty: false });
  const b = bestellungen.get(nr);
  b.bestelldatum = b.bestelldatum || datum(r[S.datum]);
  if (b.betragExport === null && r[S.betrag]) b.betragExport = zahl(r[S.betrag]);
  const sku = r[S.artikelnummer] || '';
  if (sku === CONFIG.sku || (!sku && norm(r[S.bezeichnung]) === norm(CONFIG.bezeichnung))) b.honesty = true;
}

const alle = [...bestellungen.values()].filter(b => b.honesty && b.bestelldatum).map(({ honesty, ...b }) => b);
if (!alle.length) throw new Error('Keine Honesty-Bestellung mit Bestelldatum im Export gefunden');
// Ohne Betrag ist keine eingegrenzte Suche möglich
const mitBetrag = alle.filter(b => b.betragExport > 0).sort((a, b) => a.bestelldatum.localeCompare(b.bestelldatum));
if (!mitBetrag.length) throw new Error('Keine Honesty-Bestellung mit lesbarem Betrag im Export gefunden');

// Stichprobe: gleichmäßig über den Zeitraum verteilt – je Zieltag die Bestellung mit dem nächstgelegenen Datum.
// Erste und letzte Bestellung sind immer dabei.
const zeit = b => new Date(b.bestelldatum).getTime();
const n = CONFIG.stichprobe > 0 ? Math.min(CONFIG.stichprobe, mitBetrag.length) : mitBetrag.length;
let liste = mitBetrag;
if (n < mitBetrag.length) {
  const von = zeit(mitBetrag[0]);
  const bis = zeit(mitBetrag[mitBetrag.length - 1]);
  const gewaehlt = new Set();
  for (let i = 0; i < n; i++) {
    const ziel = n === 1 ? von : von + i * (bis - von) / (n - 1);
    let beste = -1;
    mitBetrag.forEach((b, k) => {
      if (gewaehlt.has(k)) return;
      if (beste < 0 || Math.abs(zeit(b) - ziel) < Math.abs(zeit(mitBetrag[beste]) - ziel)) beste = k;
    });
    gewaehlt.add(beste);
  }
  liste = [...gewaehlt].sort((a, b) => a - b).map(k => mitBetrag[k]);
}

return [{ json: { config: CONFIG, bestellungen: liste, honestyBestellungen: alle.length, ohneBetrag: alle.length - mitBetrag.length } }];

// Token prüfen und je Bestellung eine eigene PayPal-Suche bilden. PayPal liefert je Suche höchstens 10.000 Transaktionen
// (RESULTSET_TOO_LARGE) und kennt keinen Filter nach Rechnungsnummer. Darum: Zeitraum Vortag bis +suchPufferTage
// (PayPal: max. 31 Tage) und Bruttobetrag = Bestellbetrag ± betragToleranz (Filter transaction_amount, in Cent).
const antwort = $('Token holen (PayPal)').first().json;
if (!antwort.access_token) {
  throw new Error('PayPal: kein Access-Token – Credential an "Token holen (PayPal)" prüfen. Antwort: ' + JSON.stringify(antwort).slice(0, 300));
}
const { config, bestellungen } = $('Honesty-Bestellungen sammeln').first().json;
const TAG = 86400000;
const jetzt = Date.now();
const iso = t => new Date(t).toISOString().replace(/\.\d{3}Z$/, 'Z');
const cent = x => Math.max(0, Math.round(x * 100));

return bestellungen.map(b => {
  const d = new Date(b.bestelldatum).getTime();
  return {
    json: {
      bestellnummer: b.bestellnummer,
      start: iso(d - TAG),
      ende: iso(Math.min(d + (config.suchPufferTage + 1) * TAG, jetzt) - 1000),
      betrag: `[${cent(b.betragExport - config.betragToleranz)} TO ${cent(b.betragExport + config.betragToleranz)}]`
    }
  };
});

// Ordnet die PayPal-Zahlungen den Honesty-Bestellungen zu und leitet das Präfix ab:
// Präfix = Rechnungsnummer ohne die Bestellnummer am Ende, z. B. "WC-2011892" -> "WC-".
// Ohne Treffer über die Rechnungsnummer wird zusätzlich das Feld custom_field nach der Bestellnummer durchsucht.
const { bestellungen } = $('Honesty-Bestellungen sammeln').first().json;
const TAG = 86400000;
const nummern = new Set(bestellungen.map(b => b.bestellnummer));

// Eingehende Zahlungen (positiver Betrag), je Transaktions-ID einmal
const zahlungen = new Map();
for (const seite of $input.all()) {
  for (const t of seite.json.transaction_details || []) {
    const ti = t.transaction_info || {};
    if (!ti.transaction_id || !(Number(ti.transaction_amount?.value) > 0)) continue;
    zahlungen.set(ti.transaction_id, {
      rechnungsnummer: String(ti.invoice_id || '').trim(),
      customField: String(ti.custom_field || '').trim(),
      betrag: Number(ti.transaction_amount.value),
      datum: ti.transaction_initiation_date || '',
      status: ti.transaction_status || ''
    });
  }
}

// Rechnungsnummer endet auf eine Bestellnummer; das Präfix davor darf nicht auf eine Ziffer enden
// (sonst wäre "WC-11808742" ein Treffer für 1808742)
const perRechnung = new Map();
const perCustom = new Map();
const merke = (map, nr, z) => { if (!map.has(nr)) map.set(nr, []); map.get(nr).push(z); };
for (const z of zahlungen.values()) {
  const r = z.rechnungsnummer;
  for (let i = 0; i < r.length; i++) {
    const nr = r.slice(i);
    if (nummern.has(nr) && (i === 0 || !/\d/.test(r[i - 1]))) {
      merke(perRechnung, nr, { ...z, praefix: r.slice(0, i) });
      break;
    }
  }
  for (const token of new Set(z.customField.match(/A-\d{4}-\d{2}-\d+|\d+/g) || [])) {
    if (nummern.has(token)) merke(perCustom, token, z);
  }
}

const runden = x => Math.round(x * 100) / 100;
return bestellungen.map(b => {
  const treffer = perRechnung.get(b.bestellnummer) || [];
  const ueberCustom = treffer.length ? [] : (perCustom.get(b.bestellnummer) || []);
  const alle = treffer.length ? treffer : ueberCustom;
  const z = alle[0];
  const status = treffer.length > 1 ? 'MEHRERE'
    : treffer.length === 1 ? 'GEFUNDEN'
    : ueberCustom.length ? 'NUR_CUSTOM_FIELD'
    : 'NICHT_GEFUNDEN';
  const alterTage = z ? Math.floor((Date.now() - new Date(z.datum)) / TAG) : '';
  return {
    json: {
      bestellnummer: b.bestellnummer,
      bestelldatum: b.bestelldatum,
      status,
      praefix: treffer.length ? [...new Set(treffer.map(t => t.praefix))].join(' | ') : '',
      rechnungsnummer: alle.map(t => t.rechnungsnummer).join(' | '),
      customField: z ? z.customField.slice(0, 100) : '',
      betragExport: b.betragExport,
      betragPayPal: z ? z.betrag : '',
      betragGleich: z && Number.isFinite(b.betragExport) ? Math.abs(runden(z.betrag - b.betragExport)) <= 0.01 : '',
      paypalStatus: z ? z.status : '',
      zahlungsdatum: z ? z.datum.slice(0, 10) : '',
      alterTage,
      innerhalb180Tage: z ? alterTage <= 180 : ''
    }
  };
});

// Übersicht: Präfixe, Trefferquote, Beträge, 180-Tage-Grenze und Beispiele nicht zugeordneter Rechnungsnummern
const rows = $input.all().map(i => i.json);
const zaehle = f => rows.reduce((m, r) => { const k = f(r); if (k !== null) m[k] = (m[k] || 0) + 1; return m; }, {});
const gefunden = rows.filter(r => r.status === 'GEFUNDEN');

// Zahlungen im Suchzeitraum, die keiner Honesty-Bestellung zugeordnet sind: zeigen das allgemeine Format
const zugeordnet = new Set(rows.flatMap(r => r.rechnungsnummer ? r.rechnungsnummer.split(' | ') : []));
const beispiele = new Map();
const gesehen = new Set();
for (const seite of $('Transaktionen suchen').all()) {
  for (const t of seite.json.transaction_details || []) {
    const ti = t.transaction_info || {};
    if (!ti.transaction_id || !(Number(ti.transaction_amount?.value) > 0)) continue;
    gesehen.add(ti.transaction_id);
    const r = String(ti.invoice_id || '').trim();
    if (beispiele.size < 20 && !zugeordnet.has(r) && !beispiele.has(r)) {
      beispiele.set(r, `${r || '(keine Rechnungsnummer)'} · custom_field: ${String(ti.custom_field || '').slice(0, 60) || '–'} · ${String(ti.transaction_initiation_date || '').slice(0, 10)}`);
    }
  }
}

return [{
  json: {
    honestyBestellungen: $('Honesty-Bestellungen sammeln').first().json.honestyBestellungen,
    ohneBetrag: $('Honesty-Bestellungen sammeln').first().json.ohneBetrag,
    stichprobe: rows.length,
    eingehendeZahlungenGeladen: gesehen.size,
    nachStatus: zaehle(r => r.status),
    praefixe: zaehle(r => r.status === 'GEFUNDEN' ? (r.praefix || '(kein Präfix)') : null),
    betragWeichtAb: gefunden.filter(r => r.betragGleich === false).length,
    gefundenInnerhalb180Tage: gefunden.filter(r => r.innerhalb180Tage === true).length,
    gefundenAelterAls180Tage: gefunden.filter(r => r.innerhalb180Tage === false).length,
    beispieleNichtZugeordnet: [...beispiele.values()]
  }
}];
